source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # Long runs on opposite borders are apertures whose offsets define rays.
    edges = []
    for side in ("top", "bottom", "left", "right"):
        vals = grid[0][:] if side == "top" else grid[-1][:] if side == "bottom" else [grid[r][0] for r in range(h)] if side == "left" else [grid[r][-1] for r in range(h)]
        runs = []
        i = 0
        while i < len(vals):
            if vals[i] == bg:
                i += 1
                continue
            j = i + 1
            while j < len(vals) and vals[j] == vals[i]:
                j += 1
            if j - i >= 2:
                runs.append((i, j, vals[i]))
            i = j
        edges.append((side, runs))
    pairs=[]
    for a,b in ((0,1),(2,3)):
        sa,ra=edges[a]; sb,rb=edges[b]
        for x in ra:
            for y in rb:
                if x[1]-x[0] == y[1]-y[0]:
                    pairs.append((sa,x,sb,y))
    # Marker cells activate their offset in a paired border run.
    markers=[]
    border_colors={run[2] for _,runs in edges for run in runs}
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v != bg and v not in border_colors:
                markers.append((r,c,v))
    active=[]
    for pair in pairs:
        side1,run1,side2,run2=pair
        n=run1[1]-run1[0]
        offsets=set()
        for r,c,v in markers:
            q = c if side1 in ("top","bottom") else r
            for run in (run1,run2):
                if run[0] <= q < run[1]:
                    offsets.add(q-run[0])
        for off in offsets:
            active.append((side1,run1,side2,run2,off))
    # Project each activated offset inward from both paired borders. Rays stop at markers.
    for side1,run1,side2,run2,off in active:
        color = next((v for r,c,v in markers if (c if side1 in ("top","bottom") else r) in range(run1[0],run1[1]) or (c if side1 in ("top","bottom") else r) in range(run2[0],run2[1])), None)
        if color is None:
            continue
        for side,run in ((side1,run1),(side2,run2)):
            q=run[0]+off
            if side in ("top","bottom"):
                r=0 if side=="top" else h-1
                step=1 if side=="top" else -1
                while 0 <= r < h:
                    if grid[r][q] != bg:
                        if any((r,c)==(r0,c0) for r0,c0,_ in markers): out[r][q]=4
                        elif r not in (0,h-1): break
                        else: pass
                    else: out[r][q]=color
                    r += step
            else:
                c=0 if side=="left" else w-1
                step=1 if side=="left" else -1
                while 0 <= c < w:
                    if grid[q][c] != bg:
                        if any((q,c)==(r0,c0) for r0,c0,_ in markers): out[q][c]=4
                        elif c not in (0,w-1): break
                        else: pass
                    else: out[q][c]=color
                    c += step
    for r,c,_ in markers:
        out[r][c]=4
    return out
